        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    initial begin
        clk = 0;
        reset = 1;

        // Test 1: Reset behavior and synchronous reset check
        @(posedge clk);
        #1;
        if (q !== 10'd0) begin
            $display("ERROR: Reset failed. Expected 0, got %d", q);
            errors = errors + 1;
        end

        // Deassert reset
        reset = 0;
        @(posedge clk);
        #1;
        if (q !== 10'd1) begin
            $display("ERROR: Counting after reset failed. Expected 1, got %d", q);
            errors = errors + 1;
        end

        // Test 2: Spot check several cycles of normal counting
        for (i = 2; i < 15; i = i + 1) begin
            @(posedge clk);
            #1;
            if (q !== i[9:0]) begin
                $display("ERROR: Count mismatch at step %0d. Expected %0d, got %d", i, i, q);
                errors = errors + 1;
            end
        end

        // Test 3: Fast-forward simulation to test boundary condition near 999
        // Instead of 1000 full cycles, we can force or manually verify rollover if needed,
        // but since we want concise and robust testing, let's let it run or test the boundary.
        // To save simulation time while rigorously testing the rollover:
        // Let's force q to 999 to test the terminal count and wrap-around behavior.
        @(negedge clk);
        dut.q = 10'd999;
        @(posedge clk); // This clock should see q == 999 and wrap to 0
        #1;
        if (q !== 10'd0) begin
            $display("ERROR: Rollover from 999 failed. Expected 0, got %d", q);
            errors = errors + 1;
        end

        // Test 4: Check next cycle after rollover (should be 1)
        @(posedge clk);
        #1;
        if (q !== 10'd1) begin
            $display("ERROR: Count after rollover failed. Expected 1, got %d", q);
            errors = errors + 1;
        end

        // Test 5: Asynchronous/Synchronous reset mid-count
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 10'd0) begin
            $display("ERROR: Synchronous reset mid-count failed. Expected 0, got %d", q);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        #1;
        if (q !== 10'd1) begin
            $display("ERROR: Recovery from mid-count reset failed. Expected 1, got %d", q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
